package carcinize;

import java.lang.reflect.Type;
import java.util.Map;

/** Generated by carcinize: calls the Rust port of `src/main/java/com/example/text/` through JNI. */
public final class TextRsNative {
    private TextRsNative() {}

    static {
        String path = System.getProperty("carcinize.lib.text_rs");
        if (path != null) {
            System.load(path);
        } else {
            System.loadLibrary("text_rs");
        }
    }

    private static native String call(String name, String args);

    /** Calls the port of {@code name}; its answer is converted to {@code type}. */
    public static Object invoke(String name, Type type, Object... args) {
        String answer = call(name, CarcinizeJson.write(java.util.Arrays.asList(args)));
        @SuppressWarnings("unchecked")
        Map<String, Object> parsed = (Map<String, Object>) CarcinizeJson.parse(answer);
        if (parsed.containsKey("ok")) {
            return type == void.class ? null : CarcinizeJson.convert(parsed.get("ok"), type);
        }
        String message = parsed.containsKey("error")
            ? String.valueOf(parsed.get("error"))
            : "Rust panic: " + parsed.get("panic");
        throw exception(message);
    }

    /** {@code "IllegalArgumentException: msg"} becomes that exception; anything else a RuntimeException. */
    private static RuntimeException exception(String message) {
        int colon = message.indexOf(": ");
        if (colon > 0) {
            String type = message.substring(0, colon);
            String rest = message.substring(colon + 2);
            for (String prefix : new String[] {"", "java.lang.", "java.util.", "java.io.", "java.time."}) {
                try {
                    Class<?> c = Class.forName(prefix + type);
                    if (RuntimeException.class.isAssignableFrom(c)) {
                        return (RuntimeException) c.getConstructor(String.class).newInstance(rest);
                    }
                } catch (ReflectiveOperationException e) {
                    // try the next package
                }
            }
        }
        return new RuntimeException(message);
    }
}
